package dev.industrialtechnology.client;
import org.lwjgl.input.Keyboard;import net.minecraft.client.Minecraft;import net.minecraft.client.settings.KeyBinding;import cpw.mods.fml.client.registry.ClientRegistry;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import dev.industrialtechnology.railway.EntityRollingStock;import dev.industrialtechnology.expansion.ExpansionCommand;import dev.industrialtechnology.core.IndustrialTechnology;
public final class TrainInput {private final KeyBinding up=new KeyBinding("Train: throttle",Keyboard.KEY_UP,"Industrial Railway"),down=new KeyBinding("Train: brake",Keyboard.KEY_DOWN,"Industrial Railway"),horn=new KeyBinding("Train: horn",Keyboard.KEY_H,"Industrial Railway"),gui=new KeyBinding("Train: controls",Keyboard.KEY_R,"Industrial Railway"),light=new KeyBinding("Train: headlights",Keyboard.KEY_L,"Industrial Railway");private int ticks;
 public TrainInput(){for(KeyBinding k:new KeyBinding[]{up,down,horn,gui,light})ClientRegistry.registerKeyBinding(k);}
 private boolean held(KeyBinding k){int n=k.getKeyCode();return n>0&&n<256&&Keyboard.isKeyDown(n);}
 @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;Minecraft m=Minecraft.getMinecraft();if(m.thePlayer==null||!(m.thePlayer.ridingEntity instanceof EntityRollingStock)||m.currentScreen!=null)return;EntityRollingStock train=(EntityRollingStock)m.thePlayer.ridingEntity;if(horn.isPressed())send(train,3);if(light.isPressed())send(train,4);if(gui.isPressed())send(train,5);if(++ticks%5!=0)return;if(held(m.gameSettings.keyBindJump))send(train,2);else if(held(up)||held(m.gameSettings.keyBindForward))send(train,0);else if(held(down)||held(m.gameSettings.keyBindBack))send(train,1);}
 private void send(EntityRollingStock e,int a){IndustrialTechnology.network.sendToServer(new ExpansionCommand(-1,e.getEntityId(),a,0));}
}
